	curl_setopt($ch, CURLOPT_CUSTOMREQUEST, 'GET');
	
	
	$headers = array();
	$headers[] = 'X-Shopify-Access-Token: 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';
	curl_setopt($ch, CURLOPT_HTTPHEADER, $headers);
	
	$result = json_decode(curl_exec($ch),true);
	if (curl_errno($ch)) {
	    echo 'Error:' . curl_error($ch);
	}
	curl_close($ch);
	
	foreach($result['metafields'] as $meta){
		if($meta['key']=='dashboard_name'){
			return $meta['value'];
		}
	}

}

function getProductDB($conn,$id){
	
	if($id<>''){
		$sql = "SELECT * FROM shopify_products WHERE variantid='".$id."'";
		$result = $conn->query($sql);
		
		if ($result->num_rows == 1) {
			while($row = $result->fetch_assoc()) {
				return $row;
			}
		} else {
			$sql = "SELECT * FROM shopify_products WHERE productid=".$id;
			$result = $conn->query($sql);
			if ($result->num_rows == 1) {
				// output data of each row
				while($row = $result->fetch_assoc()) {
					return $row;
				}
			}
		}
	}
	
}

